        if node["title"] == f"{scope}: Machines":
            machines_node = node
            break

    if machines_node:
        rows = table_rows(machines_node)
        for idx, row in rows:
            mid = row["machine"]
            desc = f"Machine {mid} (CPU: {row['CPU']}, Mem: {row['memory']})"
            ent_list.append({"id": mid, "description": desc})

    # Find Tasks
    log_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Task log":
            log_node = node
            break

    if log_node:
        rows = table_rows(log_node)
        tasks_seen = set()
        for idx, row in rows:
            tid = row["task"]
            if tid not in tasks_seen:
                # Use the submission row for the description
                # We can't guarantee we are on the submit row, so we'll store and update
                # or just use the current row's data as it's repeated in the log
                desc = f"Task {tid} (Job: {row['job']}, Priority: {row['priority']}, CPU: {row['CPU']}, Mem: {row['memory']}, Run Time: {row['run time']})"
                ent_list.append({"id": tid, "description": desc})
                tasks_seen.add(tid)

    return ent_list

