                })

    # Task submissions
    log_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Task log":
            log_node = node
            break

    if log_node:
        rows = table_rows(log_node)
        for idx, row in rows:
            if row["event"] == "submit":
