                    "fields": {
                        "job": row["job"],
                        "priority": int(row["priority"]),
                        "cpu": int(row["CPU"]),
                        "memory": int(row["memory"]),
                        "run_time": int(row["run time"])
                    },
                    "src": [log_node["node_id"], idx]
                })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []

    # Task log events
    log_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Task log":
            log_node = node
            break

    if log_node:
        rows = table_rows(log_node)
        for idx, row in rows:
            event = row["event"]
            if event in ["start", "finish", "evict", "fail"]:
                tid = row["task"]
                mid = row["machine"]
                entities = [tid]
                if mid != "-":
                    entities.append(mid)
                outcomes_list.append({
                    "time": float(row["time"]),
                    "kind": f"task_{event}",
                    "entities": entities,
                    "value": None,
                    "src": [log_node["node_id"], idx]
                })

    # Longest waits from Events list
    events_node = None
    for node in doc["nodes"]:
        if node["title"] == f"{scope}: Events":
            events_node = node
            break

    if events_node:
        for idx, line in enumerate(events_node["lines"]):
            match = re.search(r"The longest wait was (\d+) seconds for task (T\d+)", line)
            if match:
                wait_time = int(match.group(1))
                tid = match.group(2)
                outcomes_list.append({
                    "time": None,
                    "kind": "longest_wait",
                    "entities": [tid],
                    "value": wait_time,
                    "src": [events_node["node_id"], idx]
                })

    # Final Queue state
    for node in doc["nodes"]:
        if node["title"].startswith(f"{scope}: Queue at window end: Tasks running"):
            rows = table_rows(node)
            for idx, row in rows:
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "queue_running",
                    "entities": [row["task"], row["machine"]],
                    "value": float(row["remaining"]),
                    "src": [node["node_id"], idx]
                })
        elif node["title"].startswith(f"{scope}: Queue at window end: Tasks waiting"):
            rows = table_rows(node)
            for idx, row in rows:
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "queue_waiting",
                    "entities": [row["task"]],
                    "value": None,
                    "src": [node["node_id"], idx]
                })

    return outcomes_list

